 faq=[("Une petite dérive est-elle normale ?","Certains systèmes tolèrent une dérive très faible, précisée par le constructeur. Une dérive qui augmente n’est jamais normale."),("Pourquoi la dérive augmente-t-elle à chaud ?","L’huile chaude est plus fluide et passe plus facilement par les jeux et les joints usés.")],
