dict(slug="moteur-electrique-qui-vibre", machine="Moteur électrique", domaine=MI, niveau="Intermédiaire", date=D,
 h1="Moteur électrique qui vibre",
 title="Moteur électrique qui vibre : causes",
 desc="Vibration nouvelle sur un moteur ? Balourd, désalignement, pied bancal, roulements, défaut électrique : comment trier les causes avec des tests simples.",
 intro="Un moteur qui vibre use ses roulements, desserre ses fixations et fatigue la machine entraînée. La plupart des vibrations viennent de causes mécaniques simples : balourd, désalignement, fixations. Un test très utile : couper l’alimentation et observer si la vibration disparaît immédiatement ou ralentit avec la vitesse.",
 signes=["Vibration ressentie à la main sur le carter.","Bruit qui change, desserrage des boulons.","Roulements qui chauffent.","Vibration qui augmente avec le temps."],
 causes=[("Balourd (ventilateur, poulie, accouplement)","Vibration surtout radiale, qui suit la vitesse quand on coupe"),("Désalignement avec la machine","Vibration axiale élevée, usure de l’accouplement"),("Pied bancal ou fixations desserrées","Contrôle des pattes une par une, couple de serrage"),("Défaut électrique (rotor, alimentation)","Vibration qui disparaît dès la coupure de l’alimentation")],
 faire=["Mesurer la vibration et la comparer à la référence de la machine.","Faire le test de coupure : disparition immédiate (plutôt électrique) ou progressive (plutôt mécanique).","Resserrer les fixations et corriger un pied bancal.","Contrôler l’alignement et l’équilibrage des pièces tournantes.","Faire une analyse vibratoire si la cause n’est pas trouvée."],
 secu="Consigner avant toute intervention mécanique. Le test de coupure se fait par une personne habilitée, sans approcher les parties tournantes.",
 faq=[("Quel niveau de vibration est acceptable ?","Pour une machine de taille moyenne sur massif rigide, la norme ISO 10816-3 situe la zone bonne sous environ 1,4 mm/s et la zone à surveiller au-delà de 2,8 mm/s. L’évolution compte plus que la valeur seule."),("Pourquoi le test de coupure ?","Une vibration d’origine électrique disparaît dès la coupure ; une vibration mécanique diminue avec la vitesse.")],
 related=["ventilateur-qui-vibre","accouplement-qui-claque","lire-un-spectre-vibratoire"]),

